/**
 * TASK: Complete the MassUnit enum so it implements the provided
 * UnitConverter interface. Do not edit the interface.
 *
 * Step 1: give each constant the number of grams in one unit, and add the
 * private field and constructor that store it:
 *   GRAM 1.0, KILOGRAM 1000.0, POUND 453.59237, OUNCE 28.349523125
 *
 * Step 2: implement the interface using that field.
 * - toGrams(amount) converts an amount of THIS unit into grams:
 *   KILOGRAM.toGrams(2.5) -> 2500.0
 * - fromGrams(grams) converts grams back into THIS unit:
 *   KILOGRAM.fromGrams(2500.0) -> 2.5
 *
 * Step 3: convert(amount, from, to) converts between any two units by going
 * through grams: convert(1.0, POUND, OUNCE) -> 16.0 (to two decimals).
 */
interface UnitConverter {

    double toGrams(double amount);

    double fromGrams(double grams);
}

public enum MassUnit implements UnitConverter {

    GRAM(1.0),
    KILOGRAM(1000.0),
    POUND(453.59237),
    OUNCE(28.349523125);

    private final double gramsPerUnit;

    MassUnit(double gramsPerUnit) {
        this.gramsPerUnit = gramsPerUnit;
    }

    @Override
    public double toGrams(double amount) {
        return amount * gramsPerUnit;
    }

    @Override
    public double fromGrams(double grams) {
        return grams / gramsPerUnit;
    }

    public static double convert(double amount, MassUnit from, MassUnit to) {
        return to.fromGrams(from.toGrams(amount));
    }
}
